using System;using System.IO;using System.Linq;using System.Drawing;using System.Reflection;using System.Collections.Generic;using System.Windows.Forms;using MP1SkinStudio;
class PageProbe
{
 static BindingFlags flags=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;static List<string> results=new List<string>();static string demo,skin,output;
 static T Field<T>(object f,string name){return (T)f.GetType().GetField(name,flags).GetValue(f);}static object Call(object f,string name,params object[] args){try{return f.GetType().GetMethod(name,flags).Invoke(f,args);}catch(TargetInvocationException e){throw e.InnerException;}}
 static void Check(bool ok,string msg){if(!ok)throw new Exception(msg);}static void Test(string name,Action a){a();results.Add("PASS "+name);Console.WriteLine(results.Last());Console.Out.Flush();}
 static StudioForm Open(){var f=new StudioForm(demo);f.LoadProject(skin,"myHome.xml");f.StartPosition=FormStartPosition.Manual;f.Location=new Point(-20000,-20000);f.Show();Application.DoEvents();return f;}
 static bool Wheel(PageListBox page,Control target,int delta,Point point){long pos=(unchecked((ushort)point.X))|((long)unchecked((ushort)point.Y)<<16);var message=Message.Create(target.Handle,0x020A,new IntPtr((long)unchecked((ushort)delta)<<16),new IntPtr(pos));return Application.FilterMessage(ref message);}
 static Point Inside(PageListBox page){return page.PointToScreen(new Point(20,Math.Max(1,page.ClientSize.Height/2)));}
 [STAThread]static int Main(string[] args){try{Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);demo=args[0];skin=args[1];output=args[2];Directory.CreateDirectory(output);Run();return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
 static void Run()
 {
  var originals=Directory.GetFiles(skin,"*.xml",SearchOption.AllDirectories).ToDictionary(p=>p,p=>ProjectFile.Digest(File.ReadAllBytes(p)));var samples=Directory.GetFiles(demo,"*",SearchOption.AllDirectories).ToDictionary(p=>p,p=>ProjectFile.Digest(File.ReadAllBytes(p)));
  Test("DefaultWideHD embeds all 449 files in the sidebar with a resize divider and no popup",()=>
  {using(var f=Open()){var page=Field<PageListBox>(f,"page");Check(page.Visible&&page.Items.Count==449&&page.FindForm()==f&&page.Parent is Panel&&f.OwnedForms.Length==0,"Page list is not integrated");Check(page.HorizontalScrollbar&&page.ScrollAlwaysVisible,"List scrollbars missing");var split=page.Parent.Parent.Parent as SplitContainer;Check(split!=null&&split.Orientation==Orientation.Horizontal,"Resizable page/tree layout missing");}});
  Test("Wheel over file list scrolls while property input keeps focus and model selection",()=>
  {using(var f=Open()){var page=Field<PageListBox>(f,"page");var field=Field<Dictionary<string,TextBox>>(f,"fields")["label"];field.Focus();Application.DoEvents();var p=Field<SkinProject>(f,"project");string sig=ProjectFile.ContentSignature(p),active=p.Page;int selected=page.SelectedIndex;page.TopIndex=0;Check(Wheel(page,field,-120,Inside(page)),"Hover wheel was not routed");Check(page.TopIndex>0&&page.SelectedIndex==selected&&p.Page==active&&ProjectFile.ContentSignature(p)==sig&&field.Focused,"Scroll loaded a page, changed focus or model");Check(Wheel(page,field,120,Inside(page))&&page.TopIndex==0,"Reverse wheel failed");}});
  Test("Wheel deltas accumulate and stop safely at list boundaries without selection events",()=>
  {using(var f=Open()){var page=Field<PageListBox>(f,"page");page.TopIndex=0;int events=0;page.SelectedIndexChanged+=(s,e)=>events++;Call(page,"ScrollWheel",-60);Check(page.TopIndex==0,"Partial wheel moved early");Call(page,"ScrollWheel",-60);Check(page.TopIndex>0,"Partial deltas were lost");Call(page,"ScrollWheel",32760);Check(page.TopIndex==0,"Upper boundary failed");Call(page,"ScrollWheel",-32760);Check(page.TopIndex>0&&page.TopIndex<page.Items.Count&&events==0,"Boundary scroll changed selection");}});
  Test("Wheel outside the list and over another form is not intercepted",()=>
  {using(var f=Open()){var page=Field<PageListBox>(f,"page");var field=Field<Dictionary<string,TextBox>>(f,"fields")["label"];page.TopIndex=0;Check(!Wheel(page,field,-120,field.PointToScreen(new Point(3,3)))&&page.TopIndex==0,"Wheel outside list was swallowed");using(var other=new Form()){other.CreateControl();Check(!Wheel(page,other,-120,Inside(page))&&page.TopIndex==0,"Other form wheel intercepted");}}});
  Test("Filename filter is literal and insensitive and preserves active preview and pending drafts",()=>
  {using(var f=Open()){var page=Field<PageListBox>(f,"page");var search=Field<TextBox>(f,"pageSearch");var p=Field<SkinProject>(f,"project");var field=Field<Dictionary<string,TextBox>>(f,"fields")["label"];field.Text="pending draft";string sig=ProjectFile.ContentSignature(p),active=p.Page;search.Text=" MYVIDEO ";Check(page.Items.Count>0&&page.Items.Cast<object>().All(i=>i.ToString().IndexOf("myvideo",StringComparison.OrdinalIgnoreCase)>=0)&&page.SelectedIndex==-1&&p.Page==active&&ProjectFile.ContentSignature(p)==sig&&field.Text=="pending draft","Filter changed preview/draft or query semantics");search.Clear();Check(page.Items.Count==449&&page.SelectedItem.ToString()==active,"Clear did not restore active row");}});
  Test("Empty results explain no matches and wheel remains safe",()=>
  {using(var f=Open()){var page=Field<PageListBox>(f,"page");var search=Field<TextBox>(f,"pageSearch");string active=Field<SkinProject>(f,"project").Page;search.Text="*no-file*";Check(page.Items.Count==0&&Field<Label>(f,"pageCount").Text.Contains("No matches"),"Empty result unclear");Check(Wheel(page,search,-120,Inside(page))&&Field<SkinProject>(f,"project").Page==active,"Empty-list wheel changed preview");search.Clear();Check(page.SelectedItem.ToString()==active,"Empty filter lost selection");}});
  Test("Integrated selection loads Video and retains edits through save reopen exact export and Undo Redo",()=>
  {using(var f=Open()){var p=Field<SkinProject>(f,"project");var page=Field<PageListBox>(f,"page");var c=p.Controls.First(x=>x.Node.Child("posX")!=null&&!x.IsBound("posX"));int value=Int32.Parse(c.Get("posX"));string source=c.Source.RelativePath;p.Edit(c,new Dictionary<string,string>{{"posX",(value+1).ToString()}},"Integrated list edit");Call(f,"RefreshProject",c.Key);string text=c.Source.Text;
   page.SelectedIndex=page.FindStringExact("myvideo.xml");Application.DoEvents();Check(p.Page.Equals("myvideo.xml",StringComparison.OrdinalIgnoreCase)&&p.Sources.Values.Single(s=>s.RelativePath==source).Text==text&&p.Undo.Count==1,"List selection lost edit/history");string file=Path.Combine(output,"Integrated-Pages.mp1skinproj");Call(f,"SaveSession",file);var saved=ProjectFile.Load(file);Check(saved.Sources.Values.Single(s=>s.RelativePath==source).Text==text,"Saved session lost edit");saved.Export(Path.Combine(output,"Integrated-Pages.zip"));saved.UndoChange();Check(!saved.Dirty,"Restored Undo failed");saved.RedoChange();Check(saved.Sources.Values.Single(s=>s.RelativePath==source).Text==text,"Restored Redo failed");}});
  Test("Pending input blocks list selection without a modal and restores the active row",()=>
  {using(var f=Open()){var page=Field<PageListBox>(f,"page");var p=Field<SkinProject>(f,"project");var field=Field<Dictionary<string,TextBox>>(f,"fields")["label"];field.Text="draft";string sig=ProjectFile.ContentSignature(p),active=p.Page;page.SelectedIndex=page.FindStringExact("myvideo.xml");Check(p.Page==active&&page.SelectedItem.ToString()==active&&field.Text=="draft"&&ProjectFile.ContentSignature(p)==sig&&f.OwnedForms.Length==0&&Field<Label>(f,"status").Text.Contains("Apply Properties or Revert Inputs"),"Pending guard lost state or opened modal");}});
  Test("Failed page load restores the integrated selector and complete active session",()=>
  {using(var f=Open()){var page=Field<PageListBox>(f,"page");var p=Field<SkinProject>(f,"project");string sig=ProjectFile.ContentSignature(p),active=p.Page;typeof(StudioForm).GetField("loading",flags).SetValue(f,true);page.Items.Add("missing-probe-page.xml");page.SelectedIndex=page.Items.Count-1;typeof(StudioForm).GetField("loading",flags).SetValue(f,false);bool rejected=false;try{Call(f,"OpenSelectedPage");}catch(IOException){rejected=true;}Check(rejected&&p.Page==active&&page.SelectedItem.ToString()==active&&ProjectFile.ContentSignature(p)==sig,"Failed load did not roll back");}});
  Test("Skin reload resets the page filter and layout remains usable at minimum window size",()=>
  {using(var f=Open()){Field<TextBox>(f,"pageSearch").Text="myvideo";f.LoadProject(demo,"demo.xml");Check(Field<TextBox>(f,"pageSearch").Text==""&&Field<PageListBox>(f,"page").SelectedItem.ToString()=="demo.xml","Reload retained stale filter");f.Size=f.MinimumSize;Application.DoEvents();var page=Field<PageListBox>(f,"page");var tree=Field<TreeView>(f,"tree");Check(page.ClientSize.Height>=60&&tree.ClientSize.Height>=60&&page.Parent.ClientRectangle.Contains(page.Bounds),"Embedded browser clips at minimum size");using(var bitmap=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(bitmap,new Rectangle(0,0,f.Width,f.Height));bitmap.Save(Path.Combine(output,"Minimum.png"));}}});
  Test("Wheel message routing unregisters when its editor is disposed",()=>
  {var f=Open();var page=Field<PageListBox>(f,"page");var point=Inside(page);var target=Field<TextBox>(f,"pageSearch");IntPtr handle=target.Handle;f.Dispose();long pos=unchecked((ushort)point.X)|((long)unchecked((ushort)point.Y)<<16);var message=Message.Create(handle,0x020A,new IntPtr((long)unchecked((ushort)-120)<<16),new IntPtr(pos));Check(!Application.FilterMessage(ref message),"Disposed list retained wheel filter");});
  Test("Existing integrated-page and other menu callbacks remain usable",()=>
  {using(var f=new StudioForm(demo)){f.StartPosition=FormStartPosition.Manual;f.Location=new Point(-20000,-20000);f.Show();int checks=0;Call(f,"RunMenuUiSmoke",new Action<bool,string>((ok,name)=>{Check(ok,name);checks++;}));Check(checks==12,"Menu integration incomplete");}});
  using(var f=Open()){using(var bitmap=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(bitmap,new Rectangle(0,0,f.Width,f.Height));bitmap.Save(Path.Combine(output,"Integrated-DefaultWideHD.png"));}var clean=new SkinProject(skin);clean.OpenPage("myHome.xml");ProjectFile.Save(clean,Path.Combine(output,"DefaultWideHD-Inline.mp1skinproj"));}
  Check(originals.All(p=>ProjectFile.Digest(File.ReadAllBytes(p.Key))==p.Value),"Installed XML changed");Check(samples.All(p=>ProjectFile.Digest(File.ReadAllBytes(p.Key))==p.Value),"Demo files changed");results.Add(results.Count+" passed, 0 failed; "+originals.Count+" installed XML and "+samples.Count+" demo hashes unchanged. Synthetic wheel/message and selection events; no desktop input.");File.WriteAllLines(Path.Combine(output,"Results.txt"),results);Console.WriteLine(results.Last());
 }
}
